CREATE TABLE `customer_fulfillments` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`property_id` integer NOT NULL,`customer_id` integer NOT NULL,`reference` text NOT NULL,`mode` text NOT NULL,`status` text DEFAULT 'preparing' NOT NULL,`carrier` text DEFAULT '' NOT NULL,`tracking_number` text DEFAULT '' NOT NULL,`tracking_url` text DEFAULT '' NOT NULL,`shipped_at` text,`delivered_at` text,`pickup_ready_at` text,`pickup_appointment_at` text,`warehouse_instructions` text DEFAULT '' NOT NULL,`authorized_pickup_person` text DEFAULT '' NOT NULL,`pickup_code_hash` text,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_fulfillments_reference_unique` ON `customer_fulfillments` (`reference`); CREATE INDEX `customer_fulfillments_property_idx` ON `customer_fulfillments` (`property_id`);
CREATE TABLE `customer_fulfillment_packages` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`fulfillment_id` integer NOT NULL,`package_code` text NOT NULL,`window_ids_json` text NOT NULL,`window_codes_json` text NOT NULL,`status` text DEFAULT 'preparing' NOT NULL,`released_at` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE UNIQUE INDEX `customer_fulfillment_packages_code_unique` ON `customer_fulfillment_packages` (`fulfillment_id`,`package_code`); CREATE INDEX `customer_fulfillment_packages_fulfillment_idx` ON `customer_fulfillment_packages` (`fulfillment_id`);
CREATE TABLE `customer_pickup_signatures` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`fulfillment_id` integer NOT NULL,`user_id` integer NOT NULL,`package_ids_json` text NOT NULL,`printed_name` text NOT NULL,`signature_text` text NOT NULL,`released_by` text NOT NULL,`evidence_sha256` text NOT NULL,`idempotency_key` text NOT NULL,`signed_at` text NOT NULL); CREATE UNIQUE INDEX `customer_pickup_signatures_evidence_sha256_unique` ON `customer_pickup_signatures` (`evidence_sha256`); CREATE UNIQUE INDEX `customer_pickup_signatures_idempotency_key_unique` ON `customer_pickup_signatures` (`idempotency_key`); CREATE INDEX `customer_pickup_signatures_fulfillment_idx` ON `customer_pickup_signatures` (`fulfillment_id`);
